import json, hashlib, gzip
from pathlib import Path
from shapely.geometry import shape
from shapely.ops import unary_union, transform
from shapely.wkb import loads
from pyproj import Transformer

out=Path(__file__).resolve().parent
root=out.parents[2]
base=json.loads((out/'baseline-extract.json').read_text())
ids=base['scope_location_ids']
# Extract selected source/raw/current geometry measurements reproducibly.
kir=json.loads((out/'sources/geoBoundaries-KIR-ADM1.geojson').read_text())
nru=json.loads((out/'sources/geoBoundaries-NRU-ADM1.geojson').read_text())
trans=Transformer.from_crs('EPSG:4326','EPSG:6933',always_xy=True).transform
project=lambda g: transform(trans,g)
def geom_km(g): return project(g).area/1e6
def parts(g): return len(g.geoms) if g.geom_type=='MultiPolygon' else 1
source_kir={f['properties']['shapeName']:shape(f['geometry']) for f in kir['features']}
source_nru=[shape(f['geometry']) for f in nru['features']]
cur={i:shape(base['locations'][i]['geometry']) for i in ids}
byname={base['locations'][i]['properties']['name']:i for i in ids}
# Identify the 14-district union; all features are the official-licensed-source GDs 2005 division records.
nru_union=unary_union(source_nru)
# Stored region envelope bytes are pinned; member union is exact by topological test.
envmeta=base['region']['envelope']; envpath=root/'data/macro-foundation/envelopes-v5'/envmeta['path']
env=loads(gzip.decompress(envpath.read_bytes())); locunion=unary_union(list(cur.values()))

chains=base['complete_parent_chains']
measure={}
for i in ids:
  g=cur[i]; measure[i]={'current_parts':parts(g),'current_area_km2_equal_area':round(geom_km(g),6),'current_bbox':list(g.bounds)}
for nm,g in source_kir.items(): measure['source-KIR:'+nm]={'source_parts':parts(g),'source_area_km2_equal_area':round(geom_km(g),6),'source_bbox':list(g.bounds)}
measure['source-NRU:ADM1-district-union']={'district_feature_count':len(source_nru),'union_parts':parts(nru_union),'union_area_km2_equal_area':round(geom_km(nru_union),6),'overlap_current_fraction':round(project(cur['atlas:territory:NRU']).intersection(project(nru_union)).area/project(cur['atlas:territory:NRU']).area,8),'district_union_fraction_inside_current':round(project(cur['atlas:territory:NRU']).intersection(project(nru_union)).area/project(nru_union).area,8),'symmetric_difference_km2':round(project(cur['atlas:territory:NRU']).symmetric_difference(project(nru_union)).area/1e6,6)}

